CREATE TABLE kunden (
    kunden_nr INT PRIMARY KEY AUTO_INCREMENT,
    nachname VARCHAR(100) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL
);

CREATE TABLE bestellungen (
    bestell_nr INT PRIMARY KEY,
    kunden_nr INT NOT NULL,
    betrag DECIMAL(10, 2) NOT NULL,
    FOREIGN KEY (kunden_nr) REFERENCES kunden(kunden_nr) ON DELETE RESTRICT
);

START TRANSACTION;
UPDATE konto SET saldo = saldo - 500 WHERE konto_nr = 101;
UPDATE konto SET saldo = saldo + 500 WHERE konto_nr = 202;
COMMIT;
